"""
Renders the DAG configs into GitHub Actions workflows, one per cron-triggered
pipeline: .github/workflows/dag-<root task>.yml. Each task is a job that calls
the reusable dag-task.yml; upstream triggers become `needs`.

Usage:
    python -m dag.render           write the workflows
    python -m dag.render --check   fail if they are out of date (CI)
"""

import sys
from pathlib import Path

from dag.config import load_tasks, pipelines

WORKFLOWS_DIR = Path(__file__).parent.parent / ".github" / "workflows"
PREFIX = "dag-"

HEADER = """\
# Generated by `python -m dag.render` from dag/dags/. Do not edit by hand.
name: DAG {root}

on:
  schedule:
    - cron: "{cron}"
  workflow_dispatch:

concurrency:
  group: dag-{root}
  cancel-in-progress: false

permissions:
  contents: read

jobs:
"""

JOB = """\
  {name}:
    # {description}
{needs}    uses: ./.github/workflows/dag-task.yml
    permissions:
      contents: read
      id-token: write
    with:
      task: {name}
      dbt: {dbt}
"""


def render(tasks):
    files = {}
    for root, order in pipelines(tasks).items():
        out = HEADER.format(root=root, cron=tasks[root]["trigger"]["cron_schedule"])
        jobs = []
        for name in order:
            cfg = tasks[name]
            upstream = cfg["trigger"].get("depends_on")
            jobs.append(JOB.format(
                name=name,
                description=cfg.get("description", ""),
                needs=f"    needs: {upstream}\n" if upstream else "",
                dbt="true" if "dbt_command" in cfg else "false",
            ))
        files[WORKFLOWS_DIR / f"{PREFIX}{root}.yml"] = out + "\n".join(jobs)
    return files


def main(check):
    files = render(load_tasks())
    stale = [p for p in WORKFLOWS_DIR.glob(f"{PREFIX}*.yml") if p not in files and p.name != "dag-task.yml"]
    changed = [p for p, text in files.items() if not p.exists() or p.read_text() != text]

    if check:
        for p in changed + stale:
            print(f"out of date: {p.relative_to(WORKFLOWS_DIR.parent.parent)}")
        if changed or stale:
            print("run `python -m dag.render` and commit the result")
            return 1
        return 0

    for p, text in files.items():
        p.write_text(text)
    for p in stale:
        p.unlink()
    return 0


if __name__ == "__main__":
    sys.exit(main("--check" in sys.argv[1:]))
